import React, { useState } from "react";
import { join, keys, map, values } from "ramda";
import styled from "styled-components";
import { format, getDate, getDayOfYear, getMonth, isLeapYear } from "date-fns";
import Header from "./components/header";
import Stat from "./components/stat";
import countGematriaCore from "./lib/count-gematria-core";
import getZodiacSigns from "./lib/zodiac-sign";
import getMoonPhaseByDates from "./lib/moonphase";
import { dateNames } from "./constants";
import "./index.css";

const { freeze } = Object;

const NumbersTodayContainer = styled.div`
	background: rgba(23, 23, 24, 1);
	border: 1px solid rgba(255, 255, 255, 0.1);
	color: rgba(255, 255, 255, 0.89);
	height: 100%;
	max-height: 555px;
	margin: auto;
	margin-top: 8px;
	max-width: 407px;
	padding: 16px;
`;

const getDateName = d => dateNames[d - 1];

const makeDateStatLabels = selectedDate => ({
	dayOfYear: "Day of the Year",
	daysLeftYear: "Days Left in the Year",
	dayDigitSum: "Day/Month Digit Sum",
	dayNameDigitSums: format(selectedDate, "EEEE"),
	dayMonthSums: `${format(selectedDate, "MMMM")} ${getDateName(
		getDate(selectedDate)
	)}`,
	greekZodiac: "Greek Zodiac",
	indianZodiac: "Indian Zodiac",
	moonPhase: "Moon Phase",
});

const makeDayStats = selectedDate => {
	const dayOfYear = getDayOfYear(selectedDate);
	const daysLeftYear = isLeapYear(selectedDate)
		? 366 - dayOfYear
		: 365 - dayOfYear;
	const dayDigitSum = 1 + getMonth(selectedDate) + getDate(selectedDate);
	const dayOfWeek = format(selectedDate, "EEEE");
	const dayNameDigitSums = values(countGematriaCore(dayOfWeek)).join(", ");
	const makeDayMonthSums = selectedDate =>
		join(
			", ",
			values(
				countGematriaCore(
					`${format(selectedDate, "MMMM")} ${getDateName(
						getDate(selectedDate)
					)}`
				)
			)
		);

	const signs = getZodiacSigns(new Date(selectedDate));
	const { greek } = signs.find(result => result.greek);
	const { indian } = signs.find(result => result.indian);
	const moonPhase = getMoonPhaseByDates(new Date(selectedDate));

	return freeze({
		dayOfYear,
		daysLeftYear,
		dayDigitSum,
		dayNameDigitSums,
		dayMonthSums: makeDayMonthSums(selectedDate),
		greekZodiac: greek,
		indianZodiac: indian,
		moonPhase: moonPhase,
	});
};

export default function NumbersToday() {
	const [selectedDate, setSelectedDate] = useState(new Date());
	const dayStats = makeDayStats(selectedDate);
	const dayStatLabels = makeDateStatLabels(selectedDate);
	const handleDateChange = date =>
		Date.parse(date) ? setSelectedDate(date) : new Date();

	const makeStat = key => (
		<Stat label={dayStatLabels[key]} data={dayStats[key]} key={`stat-${key}`} />
	);

	return (
		<NumbersTodayContainer>
			<Header selectedDate={selectedDate} handleDateChange={handleDateChange} />
			{map(makeStat, keys(dayStats))}
		</NumbersTodayContainer>
	);
}
