const ACQUARIUS = 'Acquarius';
const PISCES = 'Pisces';
const ARIES = 'Aries';
const TAURUS = 'Taurus';
const GEMINI = 'Gemini';
const CANCER = 'Cancer';
const LEO = 'Leo';
const VIRGO = 'Virgo';
const LIBRA = 'Libra';
const SCORPIO = 'Scorpio';
const SAGITTARIUS = 'Sagittarius';
const CAPRICORN = 'Capricorn';

const systems = {
  greek: [
    ['Jan 01', 'Jan 20', CAPRICORN],
    ['Jan 21', 'Feb 19', ACQUARIUS],
    ['Feb 19', 'Mar 19', PISCES],
    ['Mar 20', 'Apr 18', ARIES],
    ['Apr 19', 'May 19', TAURUS],
    ['May 20', 'Jun 19', GEMINI],
    ['Jun 20', 'Jul 21', CANCER],
    ['Jul 22', 'Aug 21', LEO],
    ['Aug 22', 'Sep 21', VIRGO],
    ['Sep 22', 'Oct 21', LIBRA],
    ['Oct 22', 'Nov 20', SCORPIO],
    ['Nov 21', 'Dec 20', SAGITTARIUS],
    ['Dec 21', 'Dec 31', CAPRICORN],
  ],
  indian: [
    ['Jan 01', 'Jan 13', SAGITTARIUS],
    ['Jan 14', 'Feb 11', CAPRICORN],
    ['Feb 12', 'Mar 12', ACQUARIUS],
    ['Mar 13', 'Apr 12', PISCES],
    ['Apr 13', 'May 13', ARIES],
    ['May 14', 'Jun 14', TAURUS],
    ['Jun 15', 'Jul 17', GEMINI],
    ['Jul 16', 'Aug 17', CANCER],
    ['Aug 17', 'Sep 16', LEO],
    ['Sep 17', 'Oct 17', VIRGO],
    ['Oct 18', 'Nov 16', LIBRA],
    ['Nov 17', 'Dec 14', SCORPIO],
    ['Dec 15', 'Dec 31', SAGITTARIUS],
  ],
};

export default function getZodiacSigns(date = new Date()) {
  if (!Date.parse(date)) return null;
  const year = date.getFullYear();
  return Object.keys(systems).map((system) => {
    const row = systems[system].find(
      (entry) =>
        date >= new Date(`${entry[0]} ${year}`) &&
        date <= new Date(`${entry[1]} ${year}`)
    );
    return { [system]: (row && row[2]) || 'Not Found' };
  });
}
