import {
  add,
  compose,
  curry,
  defaultTo,
  gt,
  head,
  inc,
  indexOf,
  last,
  reduce,
  toLower,
  toString,
  reverse,
  split,
} from "ramda";
const english = "abcdefghijklmnopqrstuvwxyz";
const englishReversed = reverse(english);

const defaultToZero = defaultTo(0);
const splitNone = split("");
const splitLower = compose(splitNone, toLower);
const digitsToList = compose(splitNone, toString);
const firstToNumber = compose(Number, head);
const lastToNumber = compose(Number, last);
const firstNumber = compose(firstToNumber, digitsToList);
const secondNumber = compose(lastToNumber, digitsToList);
const indexOfChar = (key, char) => indexOf(char, key);
const incrementedIndexOfChar = compose(defaultToZero, inc, indexOfChar);
const isTwoPlusDigits = (num) => gt(num, 9);
const countedTwoDigits = compose(isTwoPlusDigits, incrementedIndexOfChar);

const reduceTwoDigitsToOne = (twodigits) =>
  add(firstNumber(twodigits), secondNumber(twodigits)) > 9
    ? addReduceTwoDigitsToOne(firstNumber(twodigits), secondNumber(twodigits))
    : add(firstNumber(twodigits), secondNumber(twodigits));

const reduceIndexofCharTwoDigits = compose(
  reduceTwoDigitsToOne,
  incrementedIndexOfChar
);
const addReduceTwoDigitsToOne = compose(reduceTwoDigitsToOne, add);

const letterValueCalculator = (type, key, char) =>
  type === "reduction"
    ? countedTwoDigits(key, char)
      ? reduceIndexofCharTwoDigits(key, char)
      : incrementedIndexOfChar(key, char)
    : incrementedIndexOfChar(key, char);

// reduceOrdinal :: (String, Number, String) -> Number
const reducer = (key, type, ag, char) =>
  add(ag, letterValueCalculator(type, key, char));

const reducerWKeyType = curry(reducer);

const selectReducer = (key, type) => reducerWKeyType(key, type);

const calculate = ({ type, word, key }) =>
  reduce(selectReducer(key, type), 0, splitLower(word));

// countGematriaCore :: (String) -> Object
const countGematriaCore = (word) => {
  return {
    english: calculate({ type: "ordinal", word, key: english }),
    englishReversed: calculate({ type: "ordinal", word, key: englishReversed }),
    reduction: calculate({ type: "reduction", word, key: english }),
    reductionReversed: calculate({
      type: "reduction",
      word,
      key: englishReversed,
    }),
  };
};

export default countGematriaCore;
