import React from 'react';
import styled from 'styled-components';
import DatePicker from 'react-datepicker';
import { add, sub } from 'date-fns';
import { AddButton, SubtractButton } from './buttons/buttons';
import 'react-datepicker/dist/react-datepicker.css';
import '../style/date-picker-overrides.css';

const PickerAdd = styled(AddButton)`
  background: #212121;
  color: rgba(255, 255, 255, 0.66);
  fill: #212121;
  height: 24px;
  width: 24px;
  &:hover {
    color: rgba(255, 255, 255, 1);
  }
`;

const PickerSubtract = styled(SubtractButton)`
  background: transparent;
  color: rgba(255, 255, 255, 0.66);
  fill: #212121;
  height: 24px;
  width: 24px;
  &:hover {
    color: rgba(255, 255, 255, 1);
  }
`;

const DateSelectContainer = styled.div`
  display: flex;
  justify-content: center;
  width: 100%;
`;

const DateSelectCell = styled.div`
  align-items: center;
  display: flex;
  flex: 1;
  height: 48px;
  justify-content: center;
  width: 100%;
`;

const AddSubtractCell = styled.div`
  align-items: center;
  display: flex;
  cursor: pointer;
  flex: 1;
  height: 48px;
  justify-content: center;
  width: 100%;
`;

export default function DateSelect({
  selectedDate,
  handleDateSelect,
  handleDateChange,
}) {
  const handleAddOne = () => {
    const newDate = add(new Date(selectedDate), { days: 1 });
    handleDateChange(newDate);
  };

  const handleSubOne = () => {
    const newDate = sub(new Date(selectedDate), { days: 1 });
    handleDateChange(newDate);
  };

  return (
    <DateSelectContainer data-testid="date-picker">
      <AddSubtractCell onClick={handleSubOne}>
        <PickerSubtract />
      </AddSubtractCell>
      <DateSelectCell>
        <DatePicker
          selected={selectedDate}
          onChange={(date) => handleDateChange(date)}
          portalId="root-portal"
        />
      </DateSelectCell>
      <AddSubtractCell onClick={handleAddOne}>
        <PickerAdd />
      </AddSubtractCell>
    </DateSelectContainer>
  );
}
