export const getYearMonthDay = (date) => ({
  year: date.getFullYear(),
  day: date.getDate(),
  month: date.getMonth() + 1,
});

export const getMoonPhase = ({ year, month, day }) => {
  if (month < 3) {
    year--;
    month += 12;
  }
  month++;
  const c = 365.25 * year;
  const e = 30.6 * month;
  let jd = c + e + day - 694039.09; // jd is total days elapsed
  jd /= 29.5305882; // divide by the moon cycle
  let b = parseInt(jd); // int(jd) -> b, take integer part of jd
  jd -= b; //subtract integer part to leave fractional part of original jd
  b = Math.round(jd * 8); // scale fraction from 0-8 and round
  return b >= 8 ? 0 : b; // 0 and 8 are the same so turn 8 into 0
};

export const phaseHuman = (phase) => {
  let humanPhase = '';
  switch (phase) {
    case 0:
      humanPhase = 'New Moon';
      break;
    case 1:
      humanPhase = 'Waxing Crescent';
      break;
    case 2:
      humanPhase = 'Quarter Moon';
      break;
    case 3:
      humanPhase = 'Waxing Gibbous';
      break;
    case 4:
      humanPhase = 'Full Moon';
      break;
    case 5:
      humanPhase = 'Waning Gibbous';
      break;
    case 6:
      humanPhase = 'Last Quarter';
      break;
    case 7:
      humanPhase = 'Waning Crescent';
      break;
    default:
      humanPhase = 'Error';
  }
  return humanPhase;
};

export const getMoonPhaseByDates = (date = new Date()) => {
  const { year, month, day } = getYearMonthDay(date);
  const moonPhase = getMoonPhase({ year, month, day });
  return phaseHuman(moonPhase);
};

export default getMoonPhaseByDates;

